"""Demo 1: The spectrum of the nuclear Hamiltonian is the periodic table.

Builds H_n = diag(1, ..., n) and checks that its eigenvalues are exactly the
atomic numbers 1, ..., n, and that the operator is self-adjoint.
"""
from __future__ import annotations
from fractions import Fraction
from typing import List


def nuclear_hamiltonian(n: int) -> List[List[Fraction]]:
    return [[Fraction(i + 1) if i == j else Fraction(0)
             for j in range(n)] for i in range(n)]


def is_symmetric(mat: List[List[Fraction]]) -> bool:
    n = len(mat)
    return all(mat[i][j] == mat[j][i] for i in range(n) for j in range(n))


def diagonal_eigenvalues(mat: List[List[Fraction]]) -> List[Fraction]:
    return sorted(mat[i][i] for i in range(len(mat)))


def main() -> None:
    for n in (5, 12, 20):
        H = nuclear_hamiltonian(n)
        spec = [int(v) for v in diagonal_eigenvalues(H)]
        table = list(range(1, n + 1))
        print(f"n={n:>2}  self-adjoint={is_symmetric(H)}  "
              f"spectrum==periodic table: {spec == table}")


if __name__ == "__main__":
    main()

"""Demo 2: Spectral-arithmetic bridges (trace, determinant, charpoly).

Verifies trace(H_n) = n(n+1)/2, det(H_n) = n!, and that the characteristic
polynomial factors as prod (X - k), whose roots are 1, ..., n.
"""
from __future__ import annotations
from fractions import Fraction
from math import factorial
from typing import List


def poly_mul(p: List[int], q: List[int]) -> List[int]:
    r = [0] * (len(p) + len(q) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            r[i + j] += a * b
    return r


def charpoly(n: int) -> List[int]:
    poly = [1]
    for k in range(1, n + 1):
        poly = poly_mul(poly, [-k, 1])  # (X - k)
    return poly


def main() -> None:
    for n in (4, 8, 15):
        tr = n * (n + 1) // 2
        det = factorial(n)
        cp = charpoly(n)
        roots_ok = all(sum(c * k ** i for i, c in enumerate(cp)) == 0
                       for k in range(1, n + 1))
        print(f"n={n:>2}  trace={tr:>4} (=n(n+1)/2)  det={det} (=n!)  "
              f"charpoly roots are 1..n: {roots_ok}")


if __name__ == "__main__":
    main()

"""Demo 3: The power-sum ladder trace(H_n^k) = 1^k + ... + n^k.

Computes trace(H_n^k) directly from the diagonal (each entry raised to the k-th
power) and compares against the classical closed forms for k = 1, 2, 3.
"""
from __future__ import annotations
from typing import Callable, Dict


def power_sum(n: int, k: int) -> int:
    return sum(j ** k for j in range(1, n + 1))


CLOSED_FORMS: Dict[int, Callable[[int], int]] = {
    1: lambda n: n * (n + 1) // 2,
    2: lambda n: n * (n + 1) * (2 * n + 1) // 6,
    3: lambda n: (n * (n + 1) // 2) ** 2,
}


def main() -> None:
    for n in (6, 10, 25):
        print(f"n={n}:")
        for k, formula in CLOSED_FORMS.items():
            lhs = power_sum(n, k)           # trace(H_n^k)
            rhs = formula(n)                # closed form
            print(f"   k={k}: trace(H^k)={lhs:>8}  closed form={rhs:>8}  "
                  f"match={lhs == rhs}")


if __name__ == "__main__":
    main()

