function BUILD_NUCLEAR_HAMILTONIAN(n):
    H <- n x n matrix of zeros
    for i in 0 .. n-1:
        H[i][i] <- i + 1        # atomic number of element i
    return H

function SPECTRUM(H):
    return [ H[i][i] for i in 0 .. n-1 ]   # diagonal readout

function SPECTRAL_INVARIANTS(n, K):
    atomic <- [1, 2, ..., n]
    trace  <- SUM(atomic)
    det    <- PRODUCT(atomic)
    for k in 1 .. K:
        power_trace[k] <- SUM(z^k for z in atomic)
    assert trace == n*(n+1)/2
    assert det   == n!
    return (trace, det, power_trace)

function E_FROM_POWER_SUMS(p[1..n]):
    e[0] <- 1
    for k in 1 .. n:
        acc <- 0
        for j in 1 .. k:
            acc <- acc + (-1)^(j-1) * e[k-j] * p[j]
        e[k] <- acc / k
    return e[1..n]
